CREATE TABLE IF NOT EXISTS suppliers (supplier_id TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL, tier TEXT NOT NULL CHECK (tier IN ('strategic', 'preferred', 'standard')) , payment_terms_days INTEGER NOT NULL CHECK (payment_terms_days > 0));
CREATE TABLE IF NOT EXISTS regions (region_id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products (product_id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, unit_cost_baseline NUMERIC(12,2) NOT NULL CHECK (unit_cost_baseline > 0));
CREATE TABLE IF NOT EXISTS purchase_orders (order_id TEXT PRIMARY KEY, order_date DATE NOT NULL, promised_date DATE NOT NULL, delivered_date DATE, supplier_id TEXT NOT NULL REFERENCES suppliers, product_id TEXT NOT NULL REFERENCES products, region_id TEXT NOT NULL REFERENCES regions, quantity INTEGER NOT NULL CHECK (quantity > 0), unit_cost NUMERIC(12,2) NOT NULL CHECK (unit_cost >= 0), shipping_cost NUMERIC(12,2) NOT NULL CHECK (shipping_cost >= 0), is_expedited BOOLEAN NOT NULL, defective_units INTEGER NOT NULL CHECK (defective_units >= 0 AND defective_units <= quantity), CHECK (promised_date >= order_date), CHECK (delivered_date IS NULL OR delivered_date >= order_date));
CREATE TABLE IF NOT EXISTS inventory_snapshots (snapshot_id TEXT PRIMARY KEY, snapshot_date DATE NOT NULL, region_id TEXT NOT NULL REFERENCES regions, product_id TEXT NOT NULL REFERENCES products, units_on_hand INTEGER NOT NULL CHECK (units_on_hand >= 0), reorder_level INTEGER NOT NULL CHECK (reorder_level >= 0));
CREATE INDEX IF NOT EXISTS ix_orders_date ON purchase_orders(order_date); CREATE INDEX IF NOT EXISTS ix_orders_supplier ON purchase_orders(supplier_id); CREATE INDEX IF NOT EXISTS ix_orders_region ON purchase_orders(region_id); CREATE INDEX IF NOT EXISTS ix_inventory_region_product ON inventory_snapshots(region_id, product_id, snapshot_date);
